// Extract the first pending executive task, or create a synthetic one for the daily run
const tasks = $input.first().json.data || [];
const task = tasks[0] || null;
return [{
  json: {
    task_id: task?.id || null,
    user_id: task?.user_id || null,
    triggered_by: 'daily_schedule',
    date: new Date().toLocaleDateString('en-US', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })
  }
}];

// Build the Gemini prompt from briefing data
const raw = $input.first().json;
const briefing = raw.briefing || {};
const date = $('Extract Task Info').first().json.date;

const hrRecent = (briefing.hr?.recent || []).map(c => `  - ${c.candidate_name} (${c.recommendation}, score: ${c.ai_score}%)`).join('\n') || '  None';
const finRecent = (briefing.finance?.recent || []).map(f => `  - ${f.category}: ৳${Number(f.amount).toLocaleString()} [${f.severity}]`).join('\n') || '  None';
const supRecent = (briefing.support?.recent || []).map(t => `  - Urgency: ${t.urgency}, Status: ${t.status}`).join('\n') || '  None';
const analytics = briefing.analytics?.latest ? `Score: ${briefing.analytics.latest.overall_score} (${briefing.analytics.latest.performance_rating})` : 'No data';

const prompt = `You are the Executive AI for Enterprise NeXus. Generate a concise daily business briefing for ${date}.

DATA:
HR — Recent CV Screenings:
${hrRecent}

Finance — Recent Transactions:
${finRecent}

Support — Recent Tickets:
${supRecent}

Analytics — ${analytics}

Write a professional executive briefing (3-4 paragraphs) covering: key highlights, risks to watch, and 2-3 recommended actions. Be direct and strategic.`;

return [{
  json: {
    prompt,
    task_id: $('Extract Task Info').first().json.task_id,
    user_id: $('Extract Task Info').first().json.user_id
  }
}];

// Extract Gemini text and build executive report payload
const geminiRes = $input.first().json;
const text = geminiRes?.candidates?.[0]?.content?.parts?.[0]?.text || 'Briefing generation failed.';
const taskCtx = $('Build Gemini Prompt').first().json;
const today = new Date().toLocaleDateString('en-US', { day: 'numeric', month: 'long', year: 'numeric' });

return [{
  json: {
    user_id: taskCtx.user_id,
    task_id: taskCtx.task_id,
    performance_summary: `## Daily Executive Briefing — ${today}\n\n${text}`
  }
}];
